import BookItem from "./BookItem";

const books = [
  { id: 1, title: "Hatchet", author: "Gary Paulsen", pages: 192, read: true },
  { id: 2, title: "Wonder", author: "R. J. Palacio", pages: 320, read: false },
  { id: 3, title: "Holes", author: "Louis Sachar", pages: 272, read: true },
  { id: 4, title: "Dog Man", author: "Dav Pilkey", pages: 240, read: true },
  { id: 5, title: "Amari and the Night Brothers", author: "B. B. Alston", pages: 416, read: false },
];

export default function App() {
  // 2. Make an array of the books that aren't read yet
  const unread = books.filter((book) => !book.read);

  // 3. Add up the pages of the books that ARE read
  const pagesRead = books.filter((book) => book.read).reduce((sum, book) => sum + book.pages, 0);

  return (
    <main>
      <h2>My shelf</h2>
      <ul id="books">
        {books.map((book) => (
          <BookItem key={book.id} book={book} />
        ))}
      </ul>

      <h2>To read</h2>
      <ul id="to-read">
        {unread.map((book) => (
          <BookItem key={book.id} book={book} />
        ))}
      </ul>

      <p id="total">Pages read: {pagesRead}</p>
    </main>
  );
}

