import { useState } from "react";
import "./App.css";

export default function App() {
  // 1. State for both scores, and 2. for the log of points
  const [red, setRed] = useState(0);
  const [blue, setBlue] = useState(0);
  const [log, setLog] = useState([]);

  function score(team) {
    if (team === "Red") setRed((r) => r + 1);
    else setBlue((b) => b + 1);
    // A new array with the new entry at the end; the old array is never changed.
    setLog((entries) => [...entries, { id: entries.length + 1, text: `${team} +1` }]);
  }

  // 3. Work out who's leading (no extra state needed!)
  let leader = "Tied";
  if (red > blue) leader = "Red leads";
  else if (blue > red) leader = "Blue leads";

  return (
    <main>
      <div className="teams">
        <section className="red">
          <h2>Red</h2>
          <p id="red-score">{red}</p>
          <button id="red-plus" onClick={() => score("Red")}>+1</button>
        </section>
        <section className="blue">
          <h2>Blue</h2>
          <p id="blue-score">{blue}</p>
          <button id="blue-plus" onClick={() => score("Blue")}>+1</button>
        </section>
      </div>
      <p id="leader">{leader}</p>
      <ol id="log">
        {log.map((entry) => (
          <li key={entry.id}>{entry.text}</li>
        ))}
      </ol>
    </main>
  );
}

